public class SeatBookingManager {
    private final ConcurrentHashMap<String, ReentrantLock> seatLocks = new ConcurrentHashMap<>();
    private final SeatRepository seatRepository;

    public boolean bookSeat(String showId, String seatId, String userId) {
        String lockKey = showId + "-" + seatId;
        ReentrantLock lock = seatLocks.computeIfAbsent(lockKey, k -> new ReentrantLock());

        if (lock.tryLock()) {
            try {
                // Critical Section: Database transaction boundary
                Seat seat = seatRepository.findByShowAndSeatId(showId, seatId);
                if (seat != null && seat.getStatus() == SeatStatus.AVAILABLE) {
                    seat.setStatus(SeatStatus.LOCKED);
                    seat.setLockedBy(userId);
                    seat.setLockExpiry(Instant.now().plusSeconds(300));
                    seatRepository.save(seat);
                    return true;
                }
                return false;
            } finally {
                lock.unlock();
            }
        }
        return false; // Could not acquire lock, another thread is processing this seat
    }
}
